import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { Invoice, InvoiceItem, Product } from '../../models/invoice';
import { InvoiceService } from '../../services/invoice-service';
import { ActivatedRoute } from '@angular/router';
import { CommonModule } from '@angular/common';
import { ProductService } from '../../services/product-service';


@Component({
  selector: 'app-order-details',
  imports: [CommonModule, ],
  templateUrl: './order-details.html',
  styleUrl: './order-details.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OrderDetails {
orders: Invoice | null = null;
product: Product | null = null;
  constructor(
    private route: ActivatedRoute,
    private orderService: InvoiceService,
     private cd: ChangeDetectorRef
  ) {}

  ngOnInit(): void {
    const id = Number(this.route.snapshot.paramMap.get('id'));
    if (id) {
      this.orderService.getInvoiceById(id).subscribe({
        next: (data) => {
          this.orders = data;
          console.log('Order details:', this.orders);
          this.cd.markForCheck();
        },
        error: (err) => console.error('Failed to load order details:', err),
      });
    }
  }
}

